INSERT INTO conditions (slug, name, summary, icon, color, sort) VALUES
  ('hypertension', jsonb_build_object('en', 'High blood pressure', 'bn', 'উচ্চ রক্তচাপ'), jsonb_build_object('en', 'Less salt, more vegetables, fruit, whole grains and pulses, and less alcohol can help keep blood pressure down.', 'bn', 'কম লবণ; বেশি সবজি, ফল, গোটা শস্য ও ডাল; আর কম অ্যালকোহল রক্তচাপ নিয়ন্ত্রণে রাখতে সাহায্য করতে পারে।'), 'heart', '#ff453a', 10),
  ('high-cholesterol', jsonb_build_object('en', 'High cholesterol', 'bn', 'উচ্চ কোলেস্টেরল'), jsonb_build_object('en', 'Swap saturated and trans fats for unsaturated oils, and eat more soluble fibre, oily fish, nuts, pulses and whole grains.', 'bn', 'স্যাচুরেটেড ও ট্রান্স ফ্যাটের বদলে আনস্যাচুরেটেড তেল ব্যবহার করুন, এবং বেশি করে দ্রবণীয় আঁশ, তৈলাক্ত মাছ, বাদাম, ডাল ও গোটা শস্য খান।'), 'droplet', '#ffd60a', 11),
  ('gout', jsonb_build_object('en', 'Gout', 'bn', 'গেঁটে বাত (গাউট)'), jsonb_build_object('en', 'Limit organ meat, red meat, some seafood, sugary drinks and alcohol; drink plenty of water and favour plant foods and low-fat dairy.', 'bn', 'অঙ্গের মাংস, লাল মাংস, কিছু সামুদ্রিক খাবার, চিনিযুক্ত পানীয় ও অ্যালকোহল সীমিত করুন; প্রচুর পানি খান এবং উদ্ভিজ্জ খাবার ও কম-চর্বির দুগ্ধজাত খাবারকে অগ্রাধিকার দিন।'), 'activity', '#0a84ff', 12),
  ('acid-reflux', jsonb_build_object('en', 'Acid reflux / heartburn', 'bn', 'অ্যাসিড রিফ্লাক্স / বুক জ্বালা'), jsonb_build_object('en', 'Smaller meals, an early dinner and fewer fatty, spicy, citrus, caffeine and chocolate triggers can ease heartburn.', 'bn', 'অল্প অল্প খাবার, আগেভাগে রাতের খাবার, আর চর্বিযুক্ত, ঝাল, লেবুজাতীয়, ক্যাফেইন ও চকলেটের মতো ট্রিগার কমালে বুক জ্বালা কমতে পারে।'), 'zap', '#a2845e', 13)
