INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Fibre may slow digestion, but trials have not shown a specific blood-sugar benefit from chia itself.', 'bn', 'আঁশ হজমের গতি কমাতে পারে, তবে গবেষণায় চিয়া সিড থেকে রক্তে শর্করার কোনো নির্দিষ্ট উপকার দেখা যায়নি।') FROM conditions c, foods f WHERE c.slug = 'diabetes' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'No liver-specific evidence; calorie-dense (about 486 kcal per 100 g), so keep to a spoonful or two.', 'bn', 'লিভারের জন্য নির্দিষ্ট কোনো প্রমাণ নেই; ক্যালরি বেশি (প্রতি ১০০ গ্রামে প্রায় ৪৮৬ কিলোক্যালরি), তাই এক-দুই চামচেই সীমিত রাখুন।') FROM conditions c, foods f WHERE c.slug = 'fatty-liver' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'No specific guidance found for this food; fine as part of a balanced diet.', 'bn', 'এই খাবারের জন্য নির্দিষ্ট কোনো নির্দেশনা পাওয়া যায়নি; সুষম খাদ্যের অংশ হিসেবে খাওয়া যায়।') FROM conditions c, foods f WHERE c.slug = 'asthma' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'No specific guidance found for this food; fine as part of a balanced diet.', 'bn', 'এই খাবারের জন্য নির্দিষ্ট কোনো নির্দেশনা পাওয়া যায়নি; সুষম খাদ্যের অংশ হিসেবে খাওয়া যায়।') FROM conditions c, foods f WHERE c.slug = 'migraine' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Very high in fibre, and dietary fibre may affect levothyroxine, so do not take it with your tablet; ask your doctor about timing.', 'bn', 'আঁশ খুব বেশি, আর খাদ্যের আঁশ লেভোথাইরক্সিনের কাজে প্রভাব ফেলতে পারে, তাই ওষুধের সঙ্গে একসাথে খাবেন না; কখন খাবেন তা ডাক্তারকে জিজ্ঞেস করুন।') FROM conditions c, foods f WHERE c.slug = 'thyroid' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'No specific guidance found for this food; fine as part of a balanced diet.', 'bn', 'এই খাবারের জন্য নির্দিষ্ট কোনো নির্দেশনা পাওয়া যায়নি; সুষম খাদ্যের অংশ হিসেবে খাওয়া যায়।') FROM conditions c, foods f WHERE c.slug = 'insomnia' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Seeds are part of the DASH plan, though human trials show no specific blood-pressure benefit from chia.', 'bn', 'বীজ DASH খাদ্য পরিকল্পনার অংশ, তবে মানুষের ওপর গবেষণায় চিয়া সিড থেকে রক্তচাপের কোনো নির্দিষ্ট উপকার দেখা যায়নি।') FROM conditions c, foods f WHERE c.slug = 'hypertension' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'A plant source of omega-3 listed in heart-healthy diet advice, but human reviews show no specific cholesterol benefit from chia alone.', 'bn', 'হৃদ্‌বান্ধব খাদ্য-পরামর্শে এটি ওমেগা-৩-এর একটি উদ্ভিজ্জ উৎস হিসেবে আছে, তবে মানুষের ওপর পর্যালোচনায় শুধু চিয়া সিড থেকে কোলেস্টেরলের কোনো নির্দিষ্ট উপকার দেখা যায়নি।') FROM conditions c, foods f WHERE c.slug = 'high-cholesterol' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Plant food; gout guidance focuses on purine-rich animal foods, sugary drinks and alcohol.', 'bn', 'উদ্ভিজ্জ খাবার; গেঁটে বাতের নির্দেশনা মূলত পিউরিন-সমৃদ্ধ প্রাণিজ খাবার, চিনিযুক্ত পানীয় ও অ্যালকোহল নিয়ে।') FROM conditions c, foods f WHERE c.slug = 'gout' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Not a listed reflux trigger; always soak it first.', 'bn', 'অ্যাসিডিটির পরিচিত ট্রিগারের তালিকায় নেই; সবসময় আগে ভিজিয়ে নিন।') FROM conditions c, foods f WHERE c.slug = 'acid-reflux' AND f.slug = 'chia-seeds' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Small studies suggest diluted vinegar may lower the sugar rise after meals, but it can alter insulin levels, so check with your doctor if you take insulin or diabetes medicines.', 'bn', 'ছোট গবেষণায় দেখা গেছে, পাতলা করা ভিনেগার খাবারের পর রক্তে শর্করা বাড়া কিছুটা কমাতে পারে, তবে এটি ইনসুলিনের মাত্রা বদলে দিতে পারে, তাই ইনসুলিন বা ডায়াবেটিসের ওষুধ নিলে ডাক্তারের সঙ্গে কথা বলে নিন।') FROM conditions c, foods f WHERE c.slug = 'diabetes' AND f.slug = 'apple-cider-vinegar' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'No liver-specific evidence and weight-loss evidence is weak; weight loss through overall diet is what the NHS advises.', 'bn', 'লিভারের জন্য নির্দিষ্ট কোনো প্রমাণ নেই এবং ওজন কমানোর প্রমাণও দুর্বল; NHS পুরো খাদ্যাভ্যাসের মাধ্যমে ওজন কমানোর পরামর্শ দেয়।') FROM conditions c, foods f WHERE c.slug = 'fatty-liver' AND f.slug = 'apple-cider-vinegar' ON CONFLICT (condition_id, food_id) DO NOTHING;
