INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'limit', jsonb_build_object('en', 'Vinegar has been reported to cause or worsen low potassium, especially with some water-pill (diuretic) blood-pressure medicines; ask your doctor first.', 'bn', 'ভিনেগারে পটাশিয়াম কমে যাওয়া বা আরও কমে যাওয়ার কথা জানা গেছে, বিশেষ করে রক্তচাপের কিছু প্রস্রাব-বাড়ানো ওষুধের (ডাইইউরেটিক) সঙ্গে; আগে ডাক্তারকে জিজ্ঞেস করুন।') FROM conditions c, foods f WHERE c.slug = 'hypertension' AND f.slug = 'apple-cider-vinegar' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'One trial saw slightly lower triglycerides, but evidence is limited; it does not replace cholesterol diet changes.', 'bn', 'একটি গবেষণায় ট্রাইগ্লিসারাইড সামান্য কম দেখা গেছে, তবে প্রমাণ সীমিত; কোলেস্টেরলের জন্য খাদ্যাভ্যাস বদলের বিকল্প এটি নয়।') FROM conditions c, foods f WHERE c.slug = 'high-cholesterol' AND f.slug = 'apple-cider-vinegar' ON CONFLICT (condition_id, food_id) DO NOTHING;
