INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Unsweetened, practically calorie-free drink (USDA); skip the sugar.', 'bn', 'চিনি ছাড়া, প্রায় ক্যালরিহীন পানীয় (USDA); চিনি দেবেন না।') FROM conditions c, foods f WHERE c.slug = 'diabetes' AND f.slug = 'green-tea' ON CONFLICT (condition_id, food_id) DO NOTHING;
INSERT INTO food_rules (condition_id, food_id, verdict, reason) SELECT c.id, f.id, 'ok', jsonb_build_object('en', 'Brewed tea is fine, but avoid green tea extract pills, which have been linked to rare liver injury.', 'bn', 'বানানো চা খাওয়া যায়, তবে সবুজ চায়ের নির্যাসের বড়ি এড়িয়ে চলুন, যার সঙ্গে বিরল লিভারের ক্ষতির সম্পর্ক পাওয়া গেছে।') FROM conditions c, foods f WHERE c.slug = 'fatty-liver' AND f.slug = 'green-tea' ON CONFLICT (condition_id, food_id) DO NOTHING;
