INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'do', NULL, jsonb_build_object('en', 'Taste before you salt', 'bn', 'লবণ দেওয়ার আগে চেখে দেখুন'), jsonb_build_object('en', 'Cook with little salt and add none at the table; WHO''s limit is under 5 g (one teaspoon) a day from all foods.', 'bn', 'অল্প লবণে রান্না করুন এবং খাওয়ার সময় পাতে লবণ নেবেন না; WHO-এর সীমা হলো সব খাবার মিলিয়ে দিনে ৫ গ্রামের কম (এক চা-চামচ)।'), 0 FROM conditions c WHERE c.slug = 'hypertension' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 0);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'dont', NULL, jsonb_build_object('en', 'Don''t snack on salty packets', 'bn', 'লবণাক্ত প্যাকেটের নাশতা খাবেন না'), jsonb_build_object('en', 'Chanachur, chips, instant noodles and processed meats carry hidden salt; swap for fruit or unsalted nuts.', 'bn', 'চানাচুর, চিপস, ইনস্ট্যান্ট নুডলস ও প্রক্রিয়াজাত মাংসে লুকানো লবণ থাকে; বদলে ফল বা লবণ ছাড়া বাদাম খান।'), 1 FROM conditions c WHERE c.slug = 'hypertension' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 1);
