INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'shield', jsonb_build_object('en', 'Don''t smoke, limit alcohol', 'bn', 'ধূমপান নয়, অ্যালকোহল সীমিত'), jsonb_build_object('en', 'Do not smoke, and avoid regularly drinking more than 14 units of alcohol a week.', 'bn', 'ধূমপান করবেন না, এবং নিয়মিত সপ্তাহে ১৪ ইউনিটের বেশি অ্যালকোহল খাওয়া এড়িয়ে চলুন।'), 2 FROM conditions c WHERE c.slug = 'hypertension' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 2);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'do', NULL, jsonb_build_object('en', 'Start with soluble fibre', 'bn', 'দ্রবণীয় আঁশ দিয়ে শুরু করুন'), jsonb_build_object('en', 'Oats, fruit or dal at breakfast help reach the 10-25 g of soluble fibre a day the TLC diet suggests.', 'bn', 'নাশতায় ওটস, ফল বা ডাল খেলে TLC ডায়েটের পরামর্শ মতো দিনে ১০–২৫ গ্রাম দ্রবণীয় আঁশ পাওয়া সহজ হয়।'), 0 FROM conditions c WHERE c.slug = 'high-cholesterol' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 0);
