INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'footprints', jsonb_build_object('en', 'Move 150 minutes a week', 'bn', 'সপ্তাহে ১৫০ মিনিট চলাফেরা করুন'), jsonb_build_object('en', 'Aim for 150 minutes of moderate activity, or 75 minutes of vigorous activity, a week.', 'bn', 'সপ্তাহে ১৫০ মিনিট মাঝারি বা ৭৫ মিনিট জোরালো শারীরিক পরিশ্রমের লক্ষ্য রাখুন।'), 0 FROM conditions c WHERE c.slug = 'high-cholesterol' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 0);
INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'shield', jsonb_build_object('en', 'Stop smoking', 'bn', 'ধূমপান ছাড়ুন'), jsonb_build_object('en', 'Smoking can raise cholesterol; NHS stop-smoking services can help.', 'bn', 'ধূমপান কোলেস্টেরল বাড়াতে পারে; NHS-এর ধূমপান ছাড়ার সেবা সাহায্য করতে পারে।'), 1 FROM conditions c WHERE c.slug = 'high-cholesterol' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 1);
INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'shield', jsonb_build_object('en', 'Keep alcohol low', 'bn', 'অ্যালকোহল কম রাখুন'), jsonb_build_object('en', 'Alcohol raises triglycerides; if you drink, stay within 14 units a week with drink-free days.', 'bn', 'অ্যালকোহল ট্রাইগ্লিসারাইড বাড়ায়; খেলে সপ্তাহে ১৪ ইউনিটের মধ্যে থাকুন এবং কিছু দিন একদম না খেয়ে থাকুন।'), 2 FROM conditions c WHERE c.slug = 'high-cholesterol' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 2);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'do', NULL, jsonb_build_object('en', 'Sip water through the day', 'bn', 'সারাদিন অল্প অল্প করে পানি খান'), jsonb_build_object('en', 'Plenty of fluids helps flush uric acid, unless your doctor has told you to limit fluids.', 'bn', 'প্রচুর তরল খেলে ইউরিক অ্যাসিড বের হতে সাহায্য হয়, যদি না ডাক্তার আপনাকে তরল কম খেতে বলে থাকেন।'), 0 FROM conditions c WHERE c.slug = 'gout' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 0);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'dont', NULL, jsonb_build_object('en', 'No alcohol during a flare', 'bn', 'ব্যথা বাড়ার সময় অ্যালকোহল নয়'), jsonb_build_object('en', 'Avoid alcohol completely during a gout attack, and have alcohol-free days the rest of the time.', 'bn', 'গেঁটে বাতের আক্রমণের সময় অ্যালকোহল পুরোপুরি এড়িয়ে চলুন, আর বাকি সময়েও কিছু দিন একদম অ্যালকোহল ছাড়া থাকুন।'), 1 FROM conditions c WHERE c.slug = 'gout' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 1);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'dont', NULL, jsonb_build_object('en', 'Don''t feast', 'bn', 'ভূরিভোজ করবেন না'), jsonb_build_object('en', 'Large meals and heavy drinking can trigger attacks.', 'bn', 'একবারে বেশি খাবার ও বেশি মদ্যপান ব্যথার আক্রমণ ডেকে আনতে পারে।'), 2 FROM conditions c WHERE c.slug = 'gout' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 2);
