INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'footprints', jsonb_build_object('en', 'Gentle regular exercise', 'bn', 'হালকা, নিয়মিত ব্যায়াম'), jsonb_build_object('en', 'Exercise regularly but avoid intense activity that puts heavy pressure on your joints.', 'bn', 'নিয়মিত ব্যায়াম করুন, তবে যে কঠোর পরিশ্রম গিঁটে বেশি চাপ দেয় তা এড়িয়ে চলুন।'), 1 FROM conditions c WHERE c.slug = 'gout' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 1);
INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'heart', jsonb_build_object('en', 'Diet works with medicine', 'bn', 'খাদ্যাভ্যাস ওষুধের সঙ্গে কাজ করে'), jsonb_build_object('en', 'A strict low-purine diet is less reliable than medicines at preventing attacks; follow your doctor''s plan.', 'bn', 'আক্রমণ ঠেকাতে কড়া কম-পিউরিন ডায়েট ওষুধের চেয়ে কম নির্ভরযোগ্য; ডাক্তারের পরিকল্পনা মেনে চলুন।'), 2 FROM conditions c WHERE c.slug = 'gout' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 2);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'dont', NULL, jsonb_build_object('en', 'Don''t lie down after eating', 'bn', 'খাওয়ার পর শুয়ে পড়বেন না'), jsonb_build_object('en', 'Finish meals at least 3 hours before you lie down or go to bed.', 'bn', 'শোয়া বা ঘুমাতে যাওয়ার অন্তত ৩ ঘণ্টা আগে খাওয়া শেষ করুন।'), 0 FROM conditions c WHERE c.slug = 'acid-reflux' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 0);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'do', NULL, jsonb_build_object('en', 'Eat dinner early', 'bn', 'রাতের খাবার আগেভাগে খান'), jsonb_build_object('en', 'The NHS suggests your last meal 3 to 4 hours before sleep.', 'bn', 'NHS ঘুমানোর ৩ থেকে ৪ ঘণ্টা আগে দিনের শেষ খাবার খাওয়ার পরামর্শ দেয়।'), 1 FROM conditions c WHERE c.slug = 'acid-reflux' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 1);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'do', NULL, jsonb_build_object('en', 'Smaller meals, more often', 'bn', 'অল্প করে, বারবার খান'), jsonb_build_object('en', 'Eat smaller, more frequent meals instead of large ones.', 'bn', 'একবারে বেশি না খেয়ে অল্প অল্প করে বারবার খান।'), 2 FROM conditions c WHERE c.slug = 'acid-reflux' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 2);
INSERT INTO timing_rules (condition_id, kind, time_hint, title, detail, sort) SELECT c.id, 'dont', NULL, jsonb_build_object('en', 'Skip your own triggers', 'bn', 'নিজের ট্রিগারগুলো বাদ দিন'), jsonb_build_object('en', 'Triggers vary; notice which foods set off your symptoms and cut those.', 'bn', 'ট্রিগার একেকজনের একেক রকম; কোন খাবারে আপনার সমস্যা হয় খেয়াল করুন এবং সেগুলো বাদ দিন।'), 3 FROM conditions c WHERE c.slug = 'acid-reflux' AND NOT EXISTS (SELECT 1 FROM timing_rules x WHERE x.condition_id = c.id AND x.sort = 3);
INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'scale', jsonb_build_object('en', 'Raise the head of the bed', 'bn', 'খাটের মাথার দিক উঁচু করুন'), jsonb_build_object('en', 'Raise the bed head 10-20 cm with blocks so your chest is above your waist; extra pillows can make it worse.', 'bn', 'খাটের পায়ার নিচে কিছু দিয়ে মাথার দিক ১০–২০ সেমি উঁচু করুন, যাতে বুক কোমরের চেয়ে উঁচুতে থাকে; বাড়তি বালিশ সমস্যা বাড়াতে পারে।'), 0 FROM conditions c WHERE c.slug = 'acid-reflux' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 0);
INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'scale', jsonb_build_object('en', 'Loose clothes at the waist', 'bn', 'কোমরে ঢিলেঢালা পোশাক'), jsonb_build_object('en', 'Avoid tight clothing around your waist.', 'bn', 'কোমরের চারপাশে আঁটসাঁট পোশাক এড়িয়ে চলুন।'), 1 FROM conditions c WHERE c.slug = 'acid-reflux' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 1);
INSERT INTO habits (condition_id, icon, title, detail, sort) SELECT c.id, 'scale', jsonb_build_object('en', 'Weight, smoking, stress', 'bn', 'ওজন, ধূমপান, মানসিক চাপ'), jsonb_build_object('en', 'Lose weight if overweight, stop smoking, and find ways to relax.', 'bn', 'ওজন বেশি হলে কমান, ধূমপান ছাড়ুন, এবং মন শান্ত রাখার উপায় খুঁজুন।'), 2 FROM conditions c WHERE c.slug = 'acid-reflux' AND NOT EXISTS (SELECT 1 FROM habits x WHERE x.condition_id = c.id AND x.sort = 2);
INSERT INTO posts (slug, title, excerpt, body, tags, reading_minutes, published_on) VALUES ('is-there-a-fat-burning-drink', jsonb_build_object('en', 'Is there a fat-burning drink?', 'bn', 'চর্বি পোড়ানোর কোনো পানীয় কি আছে?'), jsonb_build_object('en', 'Short answer: no. No drink or seed burns body fat. Weight comes off when you eat a little less than you use over time. Some popular drinks can still help a little, and some need care.', 'bn', 'সংক্ষেপে উত্তর: না। কোনো পানীয় বা বীজ শরীরের চর্বি পোড়ায় না। দীর্ঘ সময় ধরে খরচের চেয়ে একটু কম খেলে ওজন কমে। তবু কিছু জনপ্রিয় পানীয় সামান্য সাহায্য করতে পারে, আর কিছুতে সতর্কতা দরকার।'), '{"en": ["Short answer: no. No drink or seed burns body fat. Weight comes off when you eat a little less than you use over time. Some popular drinks can still help a little, and some need care.", "Chia seeds. Chia is rich in fibre and plant omega-3, and it swells into a gel that may help you feel full. But two studies in overweight adults found no weight-loss benefit, and trials have not shown that chia itself lowers blood sugar or cholesterol. Never eat chia dry from a spoon: a 2014 case report described dry seeds swelling and blocking a man''s food pipe. Soak them in water or milk first, or stir them into oats or yogurt.", "Apple cider vinegar. Small studies suggest vinegar may soften the blood-sugar rise after a starchy meal. One three-month study saw 2 to 4 pounds of extra weight loss, which Harvard Health calls not compelling. Always dilute it, usually 1 to 2 teaspoons in a glass of water. Undiluted vinegar wears away tooth enamel, and a case report described ulcers in the food pipe from drinking a vinegar drink that was not diluted enough. Vinegar may lower potassium, which matters if you take some water pills (diuretics) for blood pressure. It can also change insulin levels, so if you take insulin or diabetes medicines, ask your doctor first.", "Warm lemon water. Its real benefit is helping you drink more water, and the NHS suggests a slice of lemon for people who find plain water dull. Warm is not better than cold. Lemon is acidic: sipping it all day can erode teeth, and citrus is a common heartburn trigger.", "Honey water. Honey is still sugar. The British Heart Foundation counts it as free sugar (about 21 kcal per teaspoon) within the 30 g daily limit for adults. It raises blood sugar, so people with diabetes should keep it small. Never give honey to babies under 12 months.", "What works: plain water, regular meals with vegetables, pulses and whole grains, less sugar and fried food, and daily activity. If you have diabetes, high blood pressure, reflux or take regular medicine, check with your doctor before starting any daily drink."], "bn": ["সংক্ষেপে উত্তর: না। কোনো পানীয় বা বীজ শরীরের চর্বি পোড়ায় না। দীর্ঘ সময় ধরে খরচের চেয়ে একটু কম খেলে ওজন কমে। তবু কিছু জনপ্রিয় পানীয় সামান্য সাহায্য করতে পারে, আর কিছুতে সতর্কতা দরকার।", "চিয়া সিড। চিয়া সিডে আঁশ ও উদ্ভিজ্জ ওমেগা-৩ প্রচুর, আর এটি ফুলে জেলের মতো হয়, যা পেট ভরা রাখতে সাহায্য করতে পারে। কিন্তু অতিরিক্ত ওজনের প্রাপ্তবয়স্কদের ওপর দুটি গবেষণায় ওজন কমানোর কোনো উপকার পাওয়া যায়নি, আর গবেষণায় দেখা যায়নি যে চিয়া সিড নিজে রক্তে শর্করা বা কোলেস্টেরল কমায়। কখনো চামচে করে শুকনো চিয়া সিড খাবেন না: ২০১৪ সালের একটি কেস রিপোর্টে শুকনো বীজ ফুলে এক ব্যক্তির খাদ্যনালি আটকে যাওয়ার কথা বলা হয়েছে। আগে পানি বা দুধে ভিজিয়ে নিন, অথবা ওটস বা দইয়ে মিশিয়ে নিন।", "আপেল সিডার ভিনেগার। ছোট গবেষণায় দেখা গেছে, শ্বেতসারযুক্ত খাবারের পর রক্তে শর্করা বাড়া ভিনেগার কিছুটা কমাতে পারে। তিন মাসের একটি গবেষণায় ২ থেকে ৪ পাউন্ড বেশি ওজন কমেছে, যাকে Harvard Health জোরালো নয় বলেছে। সবসময় পাতলা করে খান, সাধারণত এক গ্লাস পানিতে ১ থেকে ২ চা-চামচ। পাতলা না করা ভিনেগার দাঁতের এনামেল ক্ষয় করে, আর একটি কেস রিপোর্টে যথেষ্ট পাতলা না করা ভিনেগার পানীয় খেয়ে খাদ্যনালিতে ঘা হওয়ার কথা আছে। ভিনেগার পটাশিয়াম কমাতে পারে, যা গুরুত্বপূর্ণ যদি আপনি রক্তচাপের জন্য কিছু প্রস্রাব-বাড়ানো ওষুধ (ডাইইউরেটিক) খান। এটি ইনসুলিনের মাত্রাও বদলে দিতে পারে, তাই ইনসুলিন বা ডায়াবেটিসের ওষুধ খেলে আগে ডাক্তারকে জিজ্ঞেস করুন।", "কুসুম গরম লেবু-পানি। এর আসল উপকার হলো বেশি পানি খেতে সাহায্য করা, আর যাদের সাধারণ পানি পানসে লাগে, তাদের জন্য NHS এক টুকরো লেবু দেওয়ার পরামর্শ দেয়। কুসুম গরম পানি ঠান্ডার চেয়ে ভালো নয়। লেবু অম্লীয়: সারাদিন চুমুক দিলে দাঁত ক্ষয় হতে পারে, আর লেবুজাতীয় ফল বুক জ্বালার একটি সাধারণ ট্রিগার।", "মধু-পানি। মধুও চিনি। British Heart Foundation একে ফ্রি সুগার হিসেবে ধরে (প্রতি চা-চামচে প্রায় ২১ কিলোক্যালরি), যা প্রাপ্তবয়স্কদের দৈনিক ৩০ গ্রামের সীমার মধ্যে পড়ে। এটি রক্তে শর্করা বাড়ায়, তাই ডায়াবেটিস থাকলে অল্প খাওয়া উচিত। ১২ মাসের কম বয়সী শিশুকে কখনো মধু দেবেন না।", "যা কাজ করে: সাধারণ পানি, সবজি, ডাল ও গোটা শস্যসহ নিয়মিত খাবার, কম চিনি ও ভাজাপোড়া, আর প্রতিদিন শারীরিক পরিশ্রম। ডায়াবেটিস, উচ্চ রক্তচাপ বা অ্যাসিডিটি থাকলে, অথবা নিয়মিত কোনো ওষুধ খেলে, কোনো পানীয় প্রতিদিন খাওয়া শুরুর আগে ডাক্তারের সঙ্গে কথা বলে নিন।"]}'::jsonb, '["weight", "drinks", "myths"]'::jsonb, 2, '2026-11-15') ON CONFLICT (slug) DO NOTHING;
